export function pickLang() {
  try { const l = localStorage.getItem('nsyad_lang'); if (ORDER.includes(l)) return l; } catch {}
  try { const n = (navigator.language || 'en').toLowerCase(); const b = n.slice(0, 2); if (n === 'en-in') return 'hi'; if (ORDER.includes(b)) return b; } catch {}
  return 'en';
}
export function useLang() {
  const [lang, setL] = useState('en');
  useEffect(() => { setL(pickLang()); }, []);
  const setLang = (l) => { setL(l); try { localStorage.setItem('nsyad_lang', l); } catch {} };
  const i = Math.max(0, ORDER.indexOf(lang));
  const t = (k, v) => { const row = T[k]; let s = row ? row[i] || row[0] : k; if (v) for (const [a, b] of Object.entries(v)) s = s.replace('{' + a + '}', b); return s; };
  const locale = (LANGS.find((l) => l[0] === lang) || LANGS[0])[2];
  return { lang, setLang, t, locale };
}
export function LangSwitch({ lang, setLang }) {
  return <select className="lsw" value={lang} onChange={(e) => setLang(e.target.value)} aria-label="Language">{LANGS.map(([k, l]) => <option key={k} value={k}>{l}</option>)}</select>;
}
